+
+/**
+ * Executes a portable transaction under the physical SQLite client lock.
+ * @typeParam A - Callback result.
+ * @param database - Native Drizzle wrapper.
+ * @param dialect - Declared database dialect.
+ * @param run - Callback using the actual transactional database.
+ * @returns Lazy typed transaction work; native calls settle before lock release.
+ */
+export const transactionEffect = Effect.fn("Drizzle.transaction")(<A>(
+  database: unknown,
+  dialect: "pg" | "mysql" | "sqlite",
+  run: (database: unknown) => Promise<A>,
+) => {
+  if (dialect !== "sqlite") return nativeCall("transaction", () => {
+    const method = (database as { readonly transaction?: unknown }).transaction;
+    if (typeof method !== "function") throw new TypeError("Drizzle transactions are unavailable");
+    return method.call(database, run) as Promise<A>;
+  });
+  const wrapper = database as { readonly $client?: unknown };
+  const physical = wrapper.$client;
+  const key = (physical !== null && (typeof physical === "object" || typeof physical === "function"))
+    ? physical : database;
+  if (key === null || (typeof key !== "object" && typeof key !== "function")) {
+    return nativeCall<A>("transaction", () => { throw new TypeError("SQLite transactions are unavailable"); });
+  }
+  let semaphore = coordinators.get(key);
+  if (semaphore === undefined) {
+    semaphore = Semaphore.makeUnsafe(1);
+    coordinators.set(key, semaphore);
+  }
+  // Permit waiting is interruptible; once BEGIN starts no callback/driver promise
+  // may outlive the protected transaction and race rollback or a new BEGIN.
+  return semaphore.withPermit(Effect.uninterruptible(Effect.gen(function* () {
+    yield* runSql(database, "begin");
+    const exit = yield* Effect.exit(Effect.gen(function* () {
+      const value = yield* nativeCall("transaction", () => run(database));
+      yield* runSql(database, "commit");
+      return value;
+    }));
+    if (Exit.isSuccess(exit)) return exit.value;
+    const rollback = yield* Effect.exit(runSql(database, "rollback"));
+    return yield* Effect.failCause(Exit.isFailure(rollback)
+      ? Cause.combine(exit.cause, rollback.cause) : exit.cause);
+  })));
+});
